  // your code here
}

test_suite:
test('returns same reference when deps deeply equal', () => {
  const factory = vi.fn(() => ({ value: 42 }));
  const { result, rerender } = renderHook(
    ({ deps }) => useMemoDeep(factory, deps),
    { initialProps: { deps: [{ a: 1 }] } }
  );
  const first = result.current;
  rerender({ deps: [{ a: 1 }] });
  expect(result.current).toBe(first);
  expect(factory).toHaveBeenCalledTimes(1);
});

test('returns new value when deps structurally change', () => {
  let callCount = 0;
  const { result, rerender } = renderHook(
    ({ deps }) => useMemoDeep(() => ++callCount, deps),
    { initialProps: { deps: [{ a: 1 }] } }
  );
  expect(result.current).toBe(1);
  rerender({ deps: [{ a: 2 }] });
  expect(result.current).toBe(2);
});

test('computes initial value', () => {
  const { result } = renderHook(() => useMemoDeep(() => 'hello', [1, 2]));
  expect(result.current).toBe('hello');
});

test('handles nested deep equality', () => {
  const factory = vi.fn(() => 'ok');
  const { result, rerender } = renderHook(
    ({ deps }) => useMemoDeep(factory, deps),
    { initialProps: { deps: [{ x: { y: [1, 2, 3] } }] } }
  );
  rerender({ deps: [{ x: { y: [1, 2, 3] } }] });
  expect(factory).toHaveBeenCalledTimes(1);
});

// __hidden__
test('new array reference with same primitives is stable', () => {
  const factory = vi.fn(() => 'stable');
  const { rerender } = renderHook(
    ({ deps }) => useMemoDeep(factory, deps),
    { initialProps: { deps: [1, 'two', true] } }
  );
  rerender({ deps: [1, 'two', true] });
  expect(factory).toHaveBeenCalledTimes(1);
});

solution:
import { useRef } from 'react';

function deepEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((v, i) => deepEqual(v, b[i]));
  }
  if (typeof a === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every(k => deepEqual(a[k], b[k]));
  }
  return false;
}

export function useMemoDeep<T>(factory: () => T, deps: any[]): T {
  const depsRef = useRef<any[]>(deps);
  const valueRef = useRef<T | undefined>(undefined);
  const isFirst = useRef(true);

  if (isFirst.current || !deepEqual(depsRef.current, deps)) {
    depsRef.current = deps;
    valueRef.current = factory();
    isFirst.current = false;
  }

  return valueRef.current as T;
}
